// BindingVersion is one interval of a subject/role binding.
type BindingVersion struct {
	ID            int64
	Seq           int64
	SubjectID     string
	RoleID        string
	Event         string
	OccurredAt    string
	EffectiveFrom string
	EffectiveTo   string
